"use client";

import { useState, useEffect, useMemo } from "react";
import { Network, Plus, Search, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { createClient } from "@/utils/supabase/client";
import { N8nWorkflow, CreateN8nWorkflowDTO, UpdateN8nWorkflowDTO } from "@/types/n8n";
import { WorkflowCard } from "@/components/n8n/workflow-card";
import { WorkflowDialog } from "@/components/n8n/workflow-dialog";

export default function N8nPage() {
  const [workflows, setWorkflows] = useState<N8nWorkflow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");

  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingWorkflow, setEditingWorkflow] = useState<N8nWorkflow | null>(null);

  const supabase = createClient();

  useEffect(() => {
    fetchWorkflows();
  }, []);

  const fetchWorkflows = async () => {
    setIsLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        toast.error("You must be logged in to view workflows.");
        return;
      }

      const { data, error } = await supabase
        .from('n8n_workflows')
        .select('*')
        .order('is_favorite', { ascending: false })
        .order('created_at', { ascending: false });

      if (error) throw error;
      setWorkflows(data || []);
    } catch (error: any) {
      toast.error(error.message || "Failed to fetch workflows");
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredWorkflows = useMemo(() => {
    if (!searchQuery) return workflows;
    const lowerQuery = searchQuery.toLowerCase();

    return workflows.filter(w => {
      const titleMatch = w.title.toLowerCase().includes(lowerQuery);
      const descMatch = (w.description || "").toLowerCase().includes(lowerQuery);
      const categoryMatch = (w.category || "").toLowerCase().includes(lowerQuery);
      const tagsMatch = (w.tags || []).some(t => t.toLowerCase().includes(lowerQuery));
      return titleMatch || descMatch || categoryMatch || tagsMatch;
    });
  }, [workflows, searchQuery]);

  const handleOpenAdd = () => {
    setEditingWorkflow(null);
    setIsDialogOpen(true);
  };

  const handleOpenEdit = (workflow: N8nWorkflow) => {
    setEditingWorkflow(workflow);
    setIsDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    try {
      const { error } = await supabase.from('n8n_workflows').delete().eq('id', id);
      if (error) throw error;

      setWorkflows(prev => prev.filter(w => w.id !== id));
      toast.success("Workflow deleted successfully");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete workflow");
    }
  };

  const handleToggleFavorite = async (id: string, isFavorite: boolean) => {
    // Optimistic update
    setWorkflows(prev => prev.map(w => w.id === id ? { ...w, is_favorite: isFavorite } : w).sort((a, b) => {
      if (a.is_favorite && !b.is_favorite) return -1;
      if (!a.is_favorite && b.is_favorite) return 1;
      return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
    }));

    try {
      const { error } = await supabase
        .from('n8n_workflows')
        .update({ is_favorite: isFavorite })
        .eq('id', id);
      if (error) throw error;
    } catch (error: any) {
      // Revert on error
      toast.error("Failed to update favorite status");
      fetchWorkflows();
    }
  };

  const handleRunSuccess = (id: string, runTime: string) => {
    setWorkflows(prev => prev.map(w => w.id === id ? { ...w, last_run_at: runTime } : w));
  };

  const handleSaveWorkflow = async (data: CreateN8nWorkflowDTO | UpdateN8nWorkflowDTO) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Not authenticated");

    if (editingWorkflow) {
      // Update
      const { error } = await supabase
        .from('n8n_workflows')
        .update(data)
        .eq('id', editingWorkflow.id);

      if (error) throw error;
      toast.success("Workflow updated successfully");
    } else {
      // Insert
      const insertData = { ...data, user_id: user.id };
      const { error } = await supabase
        .from('n8n_workflows')
        .insert([insertData]);

      if (error) throw error;
      toast.success("Workflow created successfully");
    }

    fetchWorkflows();
  };

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
            <Network className="w-8 h-8 text-orange-500" />
            n8n Workflow Library
          </h2>
          <p className="text-muted-foreground text-lg mt-2">
            Store, manage, and trigger your automations directly from DevFlow.
          </p>
        </div>
        <Button onClick={handleOpenAdd} className="bg-orange-600 hover:bg-orange-700 text-white shrink-0">
          <Plus className="w-4 h-4 mr-2" />
          New Workflow
        </Button>
      </div>

      <div className="relative">
        <Search className="w-5 h-5 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
        <Input 
          placeholder="Search by title, description, category, or tags..." 
          className="pl-10 bg-[#111] border-white/10 text-white w-full max-w-xl"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      {isLoading ? (
        <div className="flex justify-center items-center h-64">
          <Loader2 className="w-8 h-8 text-orange-500 animate-spin" />
        </div>
      ) : filteredWorkflows.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-64 bg-[#111] border border-white/10 border-dashed rounded-xl text-center p-8">
          <Network className="w-12 h-12 text-muted-foreground mb-4 opacity-50" />
          <h3 className="text-xl font-medium text-white mb-2">No workflows found</h3>
          <p className="text-muted-foreground max-w-md mb-6">
            {searchQuery 
              ? "We couldn't find any workflows matching your search." 
              : "You haven't added any n8n workflows yet. Create one to get started!"}
          </p>
          {searchQuery ? (
            <Button variant="outline" onClick={() => setSearchQuery("")} className="border-white/10">Clear Search</Button>
          ) : (
            <Button onClick={handleOpenAdd} className="bg-orange-600 hover:bg-orange-700">Add First Workflow</Button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredWorkflows.map((workflow) => (
            <WorkflowCard 
              key={workflow.id} 
              workflow={workflow} 
              onEdit={handleOpenEdit}
              onDelete={handleDelete}
              onToggleFavorite={handleToggleFavorite}
              onRunSuccess={handleRunSuccess}
            />
          ))}
        </div>
      )}

      <WorkflowDialog 
        open={isDialogOpen} 
        onOpenChange={setIsDialogOpen}
        workflow={editingWorkflow}
        onSave={handleSaveWorkflow}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { 
  ArrowRight, FolderOpen, Globe, Code2, MessageSquare, 
  Plus, Activity, Clock, Zap
} from "lucide-react";
import { useRouter } from "next/navigation";
import { formatDistanceToNow } from "date-fns";

import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { routes } from "@/components/layout/DashboardSidebar";
import { cn } from "@/lib/utils";

interface DashboardStats {
  projects: number;
  websites: number;
  codes: number;
  chats: number;
}

interface ActivityItem {
  id: string;
  type: "project" | "website" | "code" | "chat";
  title: string;
  description?: string;
  timestamp: string;
  url: string;
}

export default function DashboardPage() {
  const router = useRouter();
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [activities, setActivities] = useState<ActivityItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Exclude the 'Dashboard' itself from the feature cards
  const features = routes.filter(r => r.href !== "/dashboard");

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const res = await fetch("/api/dashboard/stats");
        const data = await res.json();
        if (res.ok && data.success) {
          setStats(data.stats);
          setActivities(data.activities);
        }
      } catch (error) {
        console.error("Failed to fetch dashboard data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchDashboardData();
  }, []);

  const getIconForType = (type: string) => {
    switch (type) {
      case "project": return <FolderOpen className="w-5 h-5 text-blue-500" />;
      case "website": return <Globe className="w-5 h-5 text-emerald-500" />;
      case "code": return <Code2 className="w-5 h-5 text-green-500" />;
      case "chat": return <MessageSquare className="w-5 h-5 text-purple-500" />;
      default: return <Activity className="w-5 h-5 text-gray-500" />;
    }
  };

  const getBadgeColor = (type: string) => {
    switch (type) {
      case "project": return "bg-blue-500/10 text-blue-500 border-blue-500/20";
      case "website": return "bg-emerald-500/10 text-emerald-500 border-emerald-500/20";
      case "code": return "bg-green-500/10 text-green-500 border-green-500/20";
      case "chat": return "bg-purple-500/10 text-purple-500 border-purple-500/20";
      default: return "bg-gray-500/10 text-gray-500 border-gray-500/20";
    }
  };

  return (
    <div className="p-8 pb-20 max-w-7xl mx-auto space-y-8 h-full overflow-y-auto hide-scrollbar">
      {/* Header & Quick Actions */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-2"
        >
          <h2 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
            <Zap className="w-8 h-8 text-yellow-500" />
            DevFlow AI Overview
          </h2>
          <p className="text-muted-foreground text-lg">
            Monitor your activity and access your AI tools instantly.
          </p>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="flex flex-wrap gap-3"
        >
          <Button onClick={() => router.push("/dashboard/projects")} className="bg-blue-600 hover:bg-blue-700 text-white">
            <Plus className="w-4 h-4 mr-2" /> New Project
          </Button>
          <Button onClick={() => router.push("/dashboard/code-gen")} className="bg-green-600 hover:bg-green-700 text-white">
            <Code2 className="w-4 h-4 mr-2" /> Gen Code
          </Button>
          <Button onClick={() => router.push("/dashboard/chat")} className="bg-purple-600 hover:bg-purple-700 text-white">
            <MessageSquare className="w-4 h-4 mr-2" /> New Chat
          </Button>
        </motion.div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: "Active Projects", value: stats?.projects ?? "-", icon: FolderOpen, color: "text-blue-500", bg: "bg-blue-500/10" },
          { label: "Websites Generated", value: stats?.websites ?? "-", icon: Globe, color: "text-emerald-500", bg: "bg-emerald-500/10" },
          { label: "Code Snippets", value: stats?.codes ?? "-", icon: Code2, color: "text-green-500", bg: "bg-green-500/10" },
          { label: "AI Chat Sessions", value: stats?.chats ?? "-", icon: MessageSquare, color: "text-purple-500", bg: "bg-purple-500/10" }
        ].map((stat, idx) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.1 }}
          >
            <div className="glass-card p-6 rounded-2xl border border-white/10 flex items-center gap-4">
              <div className={cn("p-4 rounded-xl", stat.bg)}>
                <stat.icon className={cn("w-6 h-6", stat.color)} />
              </div>
              <div>
                <p className="text-sm font-medium text-white/50">{stat.label}</p>
                <h4 className="text-2xl font-bold text-white">
                  {isLoading ? <span className="animate-pulse">...</span> : stat.value}
                </h4>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Recent Activity Timeline */}
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="lg:col-span-2 space-y-4"
        >
          <h3 className="text-xl font-semibold text-white flex items-center gap-2">
            <Clock className="w-5 h-5 text-white/50" /> Recent Activity
          </h3>

          <div className="glass-card rounded-2xl border border-white/10 p-6">
            {isLoading ? (
              <div className="space-y-4">
                {[1, 2, 3].map(i => (
                  <div key={i} className="flex gap-4 animate-pulse">
                    <div className="w-10 h-10 rounded-full bg-white/5" />
                    <div className="flex-1 space-y-2 py-1">
                      <div className="h-4 bg-white/5 rounded w-3/4" />
                      <div className="h-3 bg-white/5 rounded w-1/4" />
                    </div>
                  </div>
                ))}
              </div>
            ) : activities.length === 0 ? (
              <div className="text-center py-12 text-white/40 flex flex-col items-center">
                <Activity className="w-12 h-12 mb-4 opacity-20" />
                <p>No recent activity found.</p>
                <p className="text-sm mt-1">Start by creating a project or generating some code!</p>
              </div>
            ) : (
              <div className="relative border-l border-white/10 ml-5 space-y-8 pb-4">
                {activities.map((activity, idx) => (
                  <div key={`${activity.id}-${idx}`} className="relative pl-8 group">
                    <span className="absolute -left-5 top-1 flex items-center justify-center w-10 h-10 rounded-full bg-black border border-white/10">
                      {getIconForType(activity.type)}
                    </span>

                    <div 
                      className="bg-white/5 hover:bg-white/10 border border-white/5 rounded-xl p-4 transition cursor-pointer"
                      onClick={() => router.push(activity.url)}
                    >
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-2 gap-2">
                        <div className="flex items-center gap-3">
                          <span className={cn("text-[10px] font-semibold uppercase px-2 py-1 rounded border", getBadgeColor(activity.type))}>
                            {activity.type}
                          </span>
                          <span className="text-xs text-white/40 font-mono">
                            {formatDistanceToNow(new Date(activity.timestamp), { addSuffix: true })}
                          </span>
                        </div>
                      </div>
                      <h4 className="text-base font-semibold text-white/90">{activity.title}</h4>
                      {activity.description && (
                        <p className="text-sm text-white/60 mt-2 line-clamp-2 leading-relaxed">
                          {activity.description}
                        </p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </motion.div>

        {/* Modules Grid */}
        <motion.div 
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="space-y-4"
        >
          <h3 className="text-xl font-semibold text-white flex items-center gap-2">
            Tools & Modules
          </h3>
          <div className="grid grid-cols-1 gap-4">
            {features.map((feature, index) => (
              <Card 
                key={feature.href}
                className="p-5 bg-black/40 border-white/5 hover:bg-white/10 transition cursor-pointer flex items-center justify-between group"
                onClick={() => router.push(feature.href)}
              >
                <div className="flex items-center gap-4">
                  <div className={cn("p-2.5 rounded-xl bg-white/5", feature.color)}>
                    <feature.icon className="w-6 h-6" />
                  </div>
                  <h3 className="font-medium text-white group-hover:text-white/90 transition">
                    {feature.label}
                  </h3>
                </div>
                <ArrowRight className="w-5 h-5 text-white/20 group-hover:text-white/60 transition-transform group-hover:translate-x-1" />
              </Card>
            ))}
          </div>
        </motion.div>

      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { ArrowLeft, Loader2, Settings, Trash2, CalendarDays } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { KanbanBoard } from "@/components/projects/KanbanBoard";
import { ProjectAssets } from "@/components/projects/ProjectAssets";
import { format } from "date-fns";

export default function ProjectDetailsPage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter();
  const [projectId, setProjectId] = useState<string | null>(null);
  const [project, setProject] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [activeTab, setActiveTab] = useState<"tasks" | "assets">("tasks");

  useEffect(() => {
    params.then((p) => {
      setProjectId(p.id);
    });
  }, [params]);

  useEffect(() => {
    if (!projectId) return;

    const fetchProject = async () => {
      setIsLoading(true);
      try {
        const res = await fetch(`/api/projects/${projectId}`);
        const data = await res.json();
        if (res.ok && data.success) {
          setProject(data.project);
        } else {
          toast.error(data.error || "Failed to load project details");
          router.push("/dashboard/projects");
        }
      } catch (error) {
        toast.error("Network error");
        router.push("/dashboard/projects");
      } finally {
        setIsLoading(false);
      }
    };

    fetchProject();
  }, [projectId, router]);

  const handleDeleteProject = async () => {
    if (!confirm("Are you sure you want to delete this project? All tasks will be lost.")) return;

    try {
      const res = await fetch(`/api/projects/${projectId}`, { method: "DELETE" });
      if (res.ok) {
        toast.success("Project deleted");
        router.push("/dashboard/projects");
      } else {
        toast.error("Failed to delete project");
      }
    } catch (error) {
      toast.error("Network error");
    }
  };

  if (isLoading || !project) {
    return (
      <div className="flex h-[80vh] items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-6">
      <button 
        onClick={() => router.push("/dashboard/projects")}
        className="flex items-center text-sm text-muted-foreground hover:text-white transition-colors"
      >
        <ArrowLeft className="w-4 h-4 mr-2" /> Back to Projects
      </button>

      <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 bg-white/5 border border-white/10 p-6 rounded-2xl">
        <div className="space-y-3">
          <div className="flex items-center gap-3">
            <h1 className="text-3xl font-bold text-white">{project.name}</h1>
            <Badge variant="outline" className="bg-primary/10 text-primary border-primary/20">
              {project.status === "active" ? "Active" : "Archived"}
            </Badge>
          </div>

          <p className="text-muted-foreground text-lg max-w-2xl">
            {project.description || "No description provided for this project."}
          </p>

          <div className="flex items-center gap-4 text-sm text-muted-foreground pt-2">
            <div className="flex items-center gap-1.5">
              <CalendarDays className="w-4 h-4" />
              Created {format(new Date(project.created_at), "MMM d, yyyy")}
            </div>
            {project.tech_stack?.length > 0 && (
              <div className="flex items-center gap-2">
                <span className="w-1 h-1 rounded-full bg-white/20" />
                <div className="flex gap-2">
                  {project.tech_stack.map((tech: string) => (
                    <span key={tech} className="bg-white/10 px-2 py-0.5 rounded text-xs text-white/80">
                      {tech}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="flex gap-3">
          <Button variant="outline" className="bg-white/5 border-white/10 hover:bg-white/10">
            <Settings className="w-4 h-4 mr-2" /> Settings
          </Button>
          <Button variant="destructive" onClick={handleDeleteProject} className="bg-red-500/10 text-red-500 hover:bg-red-500/20 border border-red-500/20">
            <Trash2 className="w-4 h-4 mr-2" /> Delete Project
          </Button>
        </div>
      </div>

      <div className="pt-4 border-t border-white/10">

        {/* Tabs */}
        <div className="flex items-center gap-4 border-b border-white/5 mb-6">
          <button
            onClick={() => setActiveTab("tasks")}
            className={`pb-3 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "tasks" ? "border-blue-500 text-blue-400" : "border-transparent text-white/50 hover:text-white"
            }`}
          >
            Kanban Tasks
          </button>
          <button
            onClick={() => setActiveTab("assets")}
            className={`pb-3 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "assets" ? "border-blue-500 text-blue-400" : "border-transparent text-white/50 hover:text-white"
            }`}
          >
            Linked Assets
          </button>
        </div>

        {activeTab === "tasks" ? (
          <>
            <h2 className="text-xl font-semibold text-white mb-2">Project Tasks</h2>
            <p className="text-sm text-muted-foreground">Manage your development workflow.</p>
            {projectId && <KanbanBoard projectId={projectId} />}
          </>
        ) : (
          <>
            <h2 className="text-xl font-semibold text-white mb-2">Project Assets</h2>
            <p className="text-sm text-muted-foreground mb-6">AI generated code, websites, and chat sessions linked to this project.</p>
            {projectId && <ProjectAssets projectId={projectId} />}
          </>
        )}

      </div>
    </div>
  );
}

"use client";

